class MockClock : public Clock {
 public:
  MOCK_METHOD(Timestamp, now, (), (const, override));
};

TEST(SessionTest, ExpiresAfterConfiguredTime) {
  MockClock clock;
  EXPECT_CALL(clock, now()).WillOnce(Return(ts("2026-01-01T00:00:00Z")));
  Session session(clock, std::chrono::minutes{30});
  EXPECT_TRUE(session.expired());
}  // destructor verifies the expectations

